if not _items:
    raise ValueError("Baserow returned no prompt records.")

def fields_of(item):
    data = item.get("json", {})
    nested = data.get("fields")
    return nested if isinstance(nested, dict) else data

def get_value(fields, names):
    for name in names:
        if name in fields and fields[name] is not None:
            return fields[name]
    return None

def scalar(value):
    # Baserow select and linked-record values can be returned as objects.
    if isinstance(value, dict):
        for key in ("value", "name"):
            nested = value.get(key)
            if nested is not None:
                return nested
        return value.get("id")

    # A single linked record may be represented as a one-item list.
    if isinstance(value, list) and len(value) == 1:
        return scalar(value[0])

    return value

def is_enabled(value):
    value = scalar(value)

    if isinstance(value, bool):
        return value

    if isinstance(value, (int, float)):
        return value == 1

    if isinstance(value, str):
        return value.strip().lower() in (
            "true",
            "1",
            "yes",
            "enabled",
        )

    return False

required = {
    "cv_project_selection": "project_selection",
    "cv_project_rewrite": "project_rewrite",
    "cv_work_experience_selection": "work_experience_selection",
    "cv_work_experience_rewrite": "work_experience_rewrite",
    "cv_skills_tailoring": "skills_tailoring",
    "cv_summary_rewrite": "summary_rewrite",
}

configs = {}

for item in _items:
    fields = fields_of(item)

    prompt_key = scalar(
        get_value(fields, ["Prompt Key", "Key", "prompt_key"])
    )
    enabled = get_value(fields, ["Enabled", "enabled"])
    status = scalar(get_value(fields, ["Status", "status"]))

    if not isinstance(prompt_key, str):
        continue

    prompt_key = prompt_key.strip()
    if prompt_key not in required:
        continue

    if not is_enabled(enabled):
        continue

    if not isinstance(status, str) or status.strip() != "Active":
        continue

    short_key = required[prompt_key]
    if short_key in configs:
        raise ValueError(
            f"More than one active prompt exists for '{prompt_key}'."
        )

    version = scalar(
        get_value(fields, ["Version", "Prompt Version", "version"])
    )
    template = scalar(
        get_value(
            fields,
            ["Prompt Template", "Prompt", "Template", "prompt_template"],
        )
    )
    temperature = scalar(
        get_value(fields, ["Temperature", "temperature"])
    )

    if not isinstance(template, str) or not template.strip():
        raise ValueError(f"Prompt '{prompt_key}' has no template.")

    try:
        version_value = float(version)
    except (TypeError, ValueError) as exc:
        raise ValueError(
            f"Prompt '{prompt_key}' must have a numeric version."
        ) from exc

    try:
        temperature_value = float(temperature)
    except (TypeError, ValueError) as exc:
        raise ValueError(
            f"Prompt '{prompt_key}' must have a numeric temperature."
        ) from exc

    configs[short_key] = {
        "key": prompt_key,
        "version": version_value,
        "template": template.strip(),
        "temperature": temperature_value,
    }

missing = [key for key in required.values() if key not in configs]
if missing:
    raise ValueError(
        "Missing active prompts: " + ", ".join(missing)
    )

output = {}
for short_key, config in configs.items():
    output[f"{short_key}_prompt_key"] = config["key"]
    output[f"{short_key}_prompt_version"] = config["version"]
    output[f"{short_key}_prompt_template"] = config["template"]
    output[f"{short_key}_temperature"] = config["temperature"]

return [{"json": output}]

