import json

data = _items[0]["json"]
groups = json.loads(data["skills_tailoring_response"]).get("groups")
inventory = data.get("original_skill_inventory", [])

if not isinstance(groups, list) or len(groups) != 3:
    raise ValueError("Skills output must contain exactly three groups.")

lookup = {
    skill.strip().casefold(): skill
    for skill in inventory
    if isinstance(skill, str) and skill.strip()
}

tailored = []
for group in groups:
    if not isinstance(group, dict):
        raise ValueError("Each skill group must be an object.")

    label = group.get("label")
    returned = group.get("skills")

    if not isinstance(label, str) or not label.strip():
        raise ValueError("Each skill group must have a label.")
    if not isinstance(returned, list):
        raise ValueError("Each skill group must have a skills array.")

    exact_skills = []
    seen = set()

    for skill in returned:
        if not isinstance(skill, str):
            raise ValueError("Every returned skill must be a string.")

        key = skill.strip().casefold()
        if key not in lookup:
            raise ValueError(
                f"The skills model returned a skill absent from the CV: {skill}"
            )
        if key not in seen:
            exact_skills.append(lookup[key])
            seen.add(key)

    tailored.append({
        "label": label.strip(),
        "value": ", ".join(exact_skills),
    })

return [{"json": {**data, "tailored_skills": tailored}}]

